"Listening… {#0} s": "Слушает… {0} с",
"No line of the text was heard in this take": "В этом семпле не услышано ни одной строки текста",
"Where the text ends cannot be told with confidence here ({0} of {1} lines heard in order, the last at line {2}): nothing trimmed. Whisper hears some languages badly.": "Где кончается текст, здесь уверенно не сказать (по порядку услышано {0} из {1} строк, последняя — строка {2}): ничего не обрезано. Некоторые языки Whisper слышит плохо.",
"The text runs to the end ({0} of {1}): nothing to trim": "Текст идёт до конца ({0} из {1}): обрезать нечего",
"The text ends at {0} of {1} ({2} of {3} lines heard in order).": "Текст кончается на {0} из {1} (по порядку услышано {2} из {3} строк).",
"Render this take again, cut at {0}? The same performance; only the sound stage runs.": "Озвучить этот семпл заново с обрезкой на {0}? То же исполнение; работает только звуковая стадия.",
