"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "Насколько широко адаптер меняет веса: 16 для одного голоса или инструмента, 32 для стиля, 64 для многих голосов, 128 самое большее.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Учится ли музыкальная половина (та, что пишет токены песни) и как сильно её урок тянет против якоря: 0 оставляет её базовой, только тембр; подними для дикции и стиля. Считается доля якоря от него, а не его величина.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Тянет музыкальную половину назад к базовой модели, чтобы она сохранила то, чего в наборе нет. Читай его как долю Веса AR: десятая доля даёт двигаться, равный весу держит у базы. При Весе AR 0 ничего не делает.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "Скорость обучения музыкальной половины как доля той, что выше: ручка, от которой она учится быстрее или медленнее (0.5 — вдвое медленнее). Маленький набор она быстро заучивает наизусть.",
