"As the studio made it (and the Refiner finished it), no DAW in between.": "Как его сделала студия (и доделал Огранщик), без DAW посередине.",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Как его сделала студия (и доделал Огранщик), без DAW посередине. Семпл в руках:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Открой семпл, включи его или отметь в Библиотекаре: его WAV, FLAC и MP3 появятся здесь.",
