"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(микс, каждый стем, партитура нотами, разделы маркерами: Waveform 14, Bitwig, Studio One, Cubase); оба есть и в меню семпла → «Скачать». Waveform: 14 или новее.",
"Packing…": "Упаковка…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 дней пробы со всеми функциями, потом лицензия: $60 для личного пользования или малого дела",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 или новее: бесплатно, без ограничений на дорожки и экспорт; открывает DAWproject студии (File > Import Other > Import a DAWproject file). Waveform 13 не поддерживается",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 дней без ограничений после регистрации, потом Essentials $99, Producer $199 или Studio $399 (bitwig.com, 03.10.2026); открывает DAWproject студии: микс, стемы, партитура нотами, разделы маркерами",
