"tracktion.com/products/waveform-free → the .deb of Waveform 14 for Linux → sudo apt install ./waveform14_*.deb": "tracktion.com/products/waveform-free → .deb Waveform 14 для Linux → sudo apt install ./waveform14_*.deb",
"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download: .deb для Ubuntu (sudo apt install ./bitwig-studio-*.deb) или Flatpak",
