"Ignore": "Игнорировать",
"Drag it to move them all at once, each in proportion.": "Потяни его, и все сдвинутся разом, каждая в своей пропорции.",
"💎 From Hugging Face…": "💎 С Hugging Face…",
"💎 Sets from Hugging Face": "💎 Наборы с Hugging Face",
"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "Одобренные наборы студии в том виде, в каком их опубликовал автор. Каждый приходит отдельным пространством, защищённым от удаления: семплы в MP3 с обложками, названиями и заметками. Скачивается только то, что ты попросишь.",
"Asking Hugging Face…": "Спрашиваю Hugging Face…",
"published {0}": "опубликован {0}",
"{#0} takes here": { "one": "{0} семпл здесь", "few": "{0} семпла здесь", "many": "{0} семплов здесь", "other": "{0} семпла здесь" },
"Not here yet": "Здесь ещё нет",
"Getting…": "Беру…",
"Try again": "Ещё раз",
"Restore the original…": "Вернуть оригинал…",
"Get": "Взять",
"files: {#0} of {#1}": "файлы: {0} из {1}",
"Open it on Hugging Face (new tab)": "Открыть на Hugging Face (новая вкладка)",
"“{0}” is here already": "«{0}» уже здесь",
"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Восстановление возвращает копию, опубликованную на Hugging Face: недостающие семплы приходят снова, названия и заметки возвращаются к опубликованным, а добавленное уходит из пространства (эти семплы остаются в библиотеке; его собственные подразделы остаются).\n\nЧтобы сохранить своё как есть: «Отмена», переименуй своё пространство (⋯ рядом с его именем, затем «Переименовать…») и снова «Взять»: оригинал придёт рядом, под своим именем.",
"Restore the original": "Вернуть оригинал",
"“{0}” came from Hugging Face": "«{0}» пришёл с Hugging Face",
"“{0}” restored from Hugging Face": "«{0}» восстановлен с Hugging Face",
"not on Hugging Face yet (or not open to this studio)": "на Hugging Face ещё нет (или он закрыт для этой студии)",
"its repository has no workspace.json yet": "в его репозитории ещё нет workspace.json",
"the repository asks for access first": "репозиторий сперва просит доступ",
"Hugging Face does not answer: {0}": "Hugging Face не отвечает: {0}",
"Not on Hugging Face yet": "На Hugging Face ещё нет",
"Frozen: its takes are heard, never changed": "Заморожено: семплы можно слушать, но не менять",
"Unfreeze": "Разморозить",
"Frozen with “{0}”": "Заморожен вместе с «{0}»",
"Freeze…": "Заморозить…",
"heard, never changed": "слушать, но не менять",
"Freeze “{0}”?": "Заморозить «{0}»?",
"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "Его семплы останутся как есть: их можно слушать и читать, но не менять, не перемещать и не выбрасывать, и они уходят из «Все пространства» и из поиска (семпл, который есть и в незамороженном пространстве, остаётся там). Пространство сереет; «Разморозить» в его меню ⋯ возвращает всё.",
"Freeze": "Заморозить",
"Frozen: “{0}”": "Заморожено: «{0}»",
