"unfreeze it to act on the take": "разморозь его, чтобы что-то делать с семплом",
"{#0} take frozen with its workspace: unfreeze it first": { "one": "{0} семпл заморожен вместе со своим пространством: сперва разморозь его", "few": "{0} семпла заморожены вместе со своим пространством: сперва разморозь его", "many": "{0} семплов заморожены вместе со своим пространством: сперва разморозь его", "other": "{0} семпла заморожены вместе со своим пространством: сперва разморозь его" },
"{#0} takes frozen with their workspace: unfreeze it first": { "one": "{0} семпл заморожен вместе со своим пространством: сперва разморозь его", "few": "{0} семпла заморожены вместе со своим пространством: сперва разморозь его", "many": "{0} семплов заморожены вместе со своим пространством: сперва разморозь его", "other": "{0} семпла заморожены вместе со своим пространством: сперва разморозь его" },
