"Drag a point up for a flare, down for a fade, along the song to move it; double-click to add one, double-click a point to take it out. The strength above is the top of the curve.": "Тяни точку вверх — вспышка, вниз — затухание, вдоль песни — сдвиг; двойной щелчок добавляет точку, двойной щелчок по точке убирает её. Сила наверху — это верх кривой.",
