"The draft's style as tags, the most important first, as an SD/SDXL prompt is written. «Into the form» chooses which of the two, the tags or the readable style, the draft puts in the Style field.": "Стиль черновика тегами, самое важное первым, как пишется промпт SD/SDXL. «В форму» выбирает, что из двух — теги или читаемый стиль — черновик положит в поле стиля.",
"Your saved briefs, kept by the lab (every browser sees them): picking one puts it in the box above.": "Твои сохранённые запросы, их хранит лаборатория (их видит любой браузер): выбранный встаёт в поле выше.",
