"Unload idle models after": "Выгружать простаивающие модели через",
"How long the models stay in GPU memory with nothing to do: 15 minutes to 4 hours, by 15. Then the engine unloads them, and the next song loads them again.": "Сколько модели остаются в памяти GPU без дела: от 15 минут до 4 часов, шагом 15. Потом движок их выгружает, и следующая песня загружает их снова.",
"The models leave GPU memory 15 s after a song: time enough to send the next one while they are still loaded": "Модели уходят из памяти GPU через 15 с после песни: хватит времени отправить следующую, пока они ещё загружены",
