"The instruments' covers are painted by an image model: some show an instrument not quite as it really is; the styles' covers are each take's own score.": "Обложки инструментов рисует модель изображений: на некоторых инструмент не совсем такой, как на самом деле; обложки стилей — собственная партитура каждого семпла.",
"⚠ A name in the style is a request, not a promise.": "⚠ Название в стиле — просьба, а не обещание.",
"What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten: trust the ear, not the name.": "▶ A и ▶ B играют то, что YuE2 даёт на это название, примерно девять раз из десяти: верь уху, а не названию.",
"Click a name": "Нажми на название",
"it goes into the Style prompt and onto the clipboard": "оно уходит в промпт стиля и в буфер обмена",
"its two probes, their seeds under them": "две его пробы, их сиды под ними",
"the ear heard it and kept it;": "ухо его услышало и оставило;",
"red": "красным",
": not played when named alone": ": не звучит, когда назван один",
"The pictures": "Картинки",
"painted by an image model: some show an instrument not quite as it really is": "их рисует модель изображений: на некоторых инструмент не совсем такой, как на самом деле",
"How the probes were made": "Как делались пробы",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B. Some probes are superb, and A and B agree, yet the instrument is not the one asked for. An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Что YuE2 просили сыграть, по одному инструменту или стилю за раз, пробами по две минуты (первые — по минуте), по два сида на каждую, A и B. Бывают пробы превосходные, A и B сходятся, а инструмент не тот, что просили. Инструмент формирует стиль всей вещи: назвав его, двигаешь и аранжировку. Треск или шелест бумаги, как на заезженной пластинке, — неудачный сид: сделай заново на другом.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B. Some probes are superb, and A and B agree, yet the instrument is not the one asked for.": "Что YuE2 просили сыграть, по одному инструменту или стилю за раз, пробами по две минуты (первые — по минуте), по два сида на каждую, A и B. Бывают пробы превосходные, A и B сходятся, а инструмент не тот, что просили.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too.": "Инструмент формирует стиль всей вещи: назвав его, двигаешь и аранжировку.",
"A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Треск или шелест бумаги, как на заезженной пластинке, — неудачный сид: сделай заново на другом.",
"{#0} heard by ear": "на слух услышано: {0}",
"Fails when named so: ask for it as the ancient triangular harp (the row below).": "Под этим названием не выходит: проси его как древнюю треугольную арфу (строка ниже).",
"Probed many times, without success: YuE2 does not know the shofar. The probes always give another pipe or horn, never a shofar, not even close. Its probes (below) are kept: take one as the horn or trumpet it turned out to be. Its adapter knows it: loras/shofar-yt-r16 at epoch 110, Viktor's ear: «Mind-blowing: no shofar player has heard the like. A whole meditation. One hundred percent a Yemenite shofar, an antelope horn two metres long» (167 overtrained, weak and thin; 66 undertrained, a trumpet in it).": "Пробовали много раз, без успеха: YuE2 не знает шофара. Пробы всегда дают другую дудку или рог, никогда не шофар, даже близко. Его пробы (ниже) оставлены: бери их как тот рог или трубу, которыми они оказались. Его адаптер шофар знает: loras/shofar-yt-r16 на эпохе 110, ухо Виктора: «Взрыв мозга: ни один шофарист такого не слышал. Целая медитация. Стопроцентно йеменский шофар, рог антилопы в два метра» (167 перетренирована, слабая и тонкая; 66 недотренирована, в ней труба).",
"Tested, Failed. Other pipe/horn discovered. B alone comes near a Yemenite shofar, a battle cry: still not a shofar.": "Проверено, не вышло. Вышла другая дудка или рог. Лишь B приближается к йеменскому шофару, боевой клич: и всё же не шофар.",
"Tested, Failed. Other pipe/horn discovered.": "Проверено, не вышло. Вышла другая дудка или рог.",
"Tested, Failed. Other pipe/horn discovered. Dross, kept: a spark of heavy rock in it.": "Проверено, не вышло. Вышла другая дудка или рог. Шлак, но оставлен: в нём искра тяжёлого рока.",
"Not like a horn either.": "И на рог не похоже.",
"Failed (Viktor 04.10: «unfortunately, YuE2 has no oboe»): no oboe in its probes.": "Не вышло (Виктор, 04.10: «к сожалению, гобоя у YuE2 нет»): в пробах гобоя нет.",
"No such reed: YuE2 does not play the bassoon. Both probes deleted.": "Такой трости нет: YuE2 не играет на фаготе. Обе пробы удалены.",
"Failed (Viktor 03.10: «the gong failed; deleting it»): no gong in its probes.": "Не вышло (Виктор, 03.10: «гонг провалился, удаляю»): в пробах гонга нет.",
"Fails: YuE2 gives no birdsong when asked for it alone (the 60 s probes and the 2-minute ones alike).": "Не выходит: YuE2 не даёт пения птиц, когда его просят одно (и минутные пробы, и двухминутные).",
"Not an instrument: a whole style (Viktor: «not an instrument, a whole style»). Styles → Summer cicadas.": "Не инструмент, а целый стиль (Виктор: «не инструмент, а целый стиль»). Стили → Летние цикады.",
