"The title, style, lyrics, score, both seeds and loaded music codes go. The mode, sampling, sliders, LoRAs and Sound and output stay as they are; New song puts the mode, sampling, sliders and LoRAs back to the defaults too.": "Уйдут название, стиль, текст, партитура, оба сида и загруженные музыкальные коды. Режим, сэмплинг, слайдеры, LoRA и «Звук и вывод» останутся как есть; «Новая песня» вернёт к умолчаниям и режим, сэмплинг, слайдеры и LoRA.",
"Cleared: the words, the score, the seeds and loaded codes; the mode, knobs, sliders and LoRAs stay": "Очищено: слова, партитура, сиды и загруженные коды; режим, ручки, слайдеры и LoRA остаются",
"Replace the score in the form with the example?": "Заменить партитуру в форме примером?",
"The score there now is kept nowhere else: save the song first (the Save button above) to keep it.": "Нынешняя партитура больше нигде не хранится: сначала сохрани песню (кнопка «Сохранить» выше), чтобы её сберечь.",
"Remove the score from the form?": "Убрать партитуру из формы?",
"It is kept nowhere else: save the song first (the Save button above) to keep it.": "Она больше нигде не хранится: сначала сохрани песню (кнопка «Сохранить» выше), чтобы её сберечь.",
"Create a new ABC score?": "Создать новую ABC-партитуру?",
"The score now in the form is written over by the one planned from the style and the lyrics.": "Партитура, что сейчас в форме, будет заменена той, что спланирована по стилю и тексту.",
"Put {0} in place of the lyrics?": "Поставить {0} вместо текста?",
"The words now in the box go; Ctrl+Z in the box brings them back.": "Слова, что сейчас в поле, уйдут; Ctrl+Z в поле вернёт их.",
"{0} is not UTF-8 text: save it as UTF-8 and open it again": "{0} — не текст UTF-8: сохрани его в UTF-8 и открой снова",
"{0} is empty": "{0} пуст",
"Saved: the song in the form, the Writer's open document, the settings": "Сохранено: песня в форме, открытый документ Писателя, настройки",
