"Out of GPU memory for the sound: {#0} of {#1} GB free when {#2} variations of {#3} s needed more. A smaller copy of the model (Q8_0) or fewer probes at once leaves it room.": "Не хватило памяти GPU для звука: свободно {#0} из {#1} ГБ, а вариациям ({#2}) по {#3} с нужно было больше. Место оставит меньшая копия модели (Q8_0) или меньше проб за раз.",
"Out of GPU memory for decoding the sound: {#0} of {#1} GB free for a tile of {#2} frames. A smaller copy of the model (Q8_0) or fewer probes at once leaves it room.": "Не хватило памяти GPU для декодирования звука: свободно {#0} из {#1} ГБ на тайл в {#2} кадров. Место оставит меньшая копия модели (Q8_0) или меньше проб за раз.",
"{0} Switch the engine to {1}? It is {2} It loads with the next song; ☰ → Model takes it back.": "{0}\n\nПереключить движок на {1}? Она {2} Она загрузится со следующей песней; ☰ → Модель вернёт прежнюю.",
"near lossless, about half the size: the sound hardly changes.": "почти без потерь, примерно вдвое меньше: звук почти не меняется.",
