"Auto for {#0} GB: whole context, VAE tiles {#1}; the backbone and keeping models loaded stay your choice. Press Save to apply.": "Авто для {#0} ГБ: весь контекст, тайлы VAE {#1}; основа и удержание моделей в памяти — на твой выбор. Нажми «Сохранить», чтобы применить.",
