"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "Доли, которые не несёт гласная, считаются со слогами в полосе каждой строки (светлее): слово без гласной (с, в, к, з, й, ў) и смычка перед аффрикатой внутри слова (глу-п-цо́в)",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "Клавиши редактора текста, как в mcedit:\nAlt+K  отметить строку курсора (ещё раз: снять метку)\nAlt+J  следующая метка · Alt+Shift+J предыдущая\nAlt+O  очистить метки (и Alt+Shift+K)\nAlt+L  перейти к строке по номеру\nCtrl+Y  удалить строку\nAlt+↑ Alt+↓  сдвинуть строку или выделенные строки\n[ в начале строки или Ctrl+Space  теги секций\nCtrl+F  поиск в поле\nAlt+I  шпаргалка инструментов и стилей\nCtrl+Z  отменить правку",
"Already in the lyrics, line {0}: a song has one": "Уже есть в тексте, строка {0}: в песне он один",
