"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "ТЕСТ: ни один из 110 официальных примеров его не пишет, так что YuE2 может спеть его как слова или пропустить. Послушай, прежде чем оставить.",
