"Precision": "Точность",
"Auto ({#0} GB found: context {#1}, VAE tiles {#2})": "Авто (найдено {#0} ГБ: контекст {#1}, тайлы VAE {#2})",
"Auto ({#0} GB found: whole context, VAE tiles {#1})": "Авто (найдено {#0} ГБ: весь контекст, тайлы VAE {#1})",
"Auto ({#0} GB found: too small for YuE2)": "Авто (найдено {#0} ГБ: мало для YuE2)",
"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: context {#2}, VAE tiles {#3})": "Авто (найдено {#0} ГБ, предел {#1} ГБ в «Движок → Видеокарты»: контекст {#2}, тайлы VAE {#3})",
"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: whole context, VAE tiles {#2})": "Авто (найдено {#0} ГБ, предел {#1} ГБ в «Движок → Видеокарты»: весь контекст, тайлы VAE {#2})",
"Auto ({#0} GB found, its limit {#1} GB in Engine → GPUs: too small for YuE2)": "Авто (найдено {#0} ГБ, предел {#1} ГБ в «Движок → Видеокарты»: мало для YuE2)",
"The most of the card’s memory the studio’s work may take, the rest left to what else runs on it (a laptop’s desktop and browser): Compute’s Auto plans the engine’s knobs for the studio card’s limit, and the lab gives a card a job only when it fits under its limit": "Наибольшая доля памяти карты, которую могут занять задачи студии, остальное — тому, что ещё на ней идёт (десктоп и браузер ноутбука): «Авто» в «Вычислениях» планирует ручки движка под предел студийной карты, а лаборатория даёт карте задачу, только если она помещается под её пределом",
"Look for a new release": "Искать новый релиз",
"When one is out": "Когда выйдет",
"release candidates too": "и кандидаты в релиз",
"The log in a window of its own": "Журнал в отдельном окне",
"The log in a window of its own: over every window where the browser can (Chrome), else one to carry to another monitor": "Журнал в отдельном окне: поверх всех окон, где браузер это умеет (Chrome), иначе — окно, которое можно унести на другой монитор",
"The server's log: the engine and the lab": "Журнал сервера: движок и лаборатория",
"The Artist's own log: what was asked, what the lab answered, each run's way to its end; kept in this browser": "Собственный журнал Художника: что просили, что ответила лаборатория, путь каждого рана до конца; хранится в этом браузере",
"Which log": "Какой журнал",
"The log's width": "Ширина журнала",
"Drag to widen the log, up to 1200 px; a double click gives its own width back": "Тяни, чтобы расширить журнал, до 1200 px; двойной клик вернёт исходную ширину",
"The Artist's log copied": "Журнал Художника скопирован",
"the Artist's log is empty": "журнал Художника пуст",
