"⚠ {0}: {#1} on the music half is past its limit {#2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {#1} на музыкальной половине — выше её предела {#2}: партитура обычно ломается после 70–200 токенов.",
"⚠ {0}: {#1} on the sound half is past its limit {#2}.": "⚠ {0}: {#1} на звуковой половине — выше её предела {#2}.",
"⚠ The sound half carries {#0} together: by ear, 2.0 together brought a heavy bass (05.10.2026). Lower some, or drag Sound, together.": "⚠ Звуковая половина несёт {#0} вместе: на слух 2.0 вместе дали тяжёлый бас (05.10.2026). Убавь какие-то или потяни «Звук, вместе».",
"⚠ The music half carries {#0} together, past the shared ceiling {#1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ Музыкальная половина несёт {#0} вместе, выше общего потолка {#1}: такие тяжёлые раны каждый раз писали сломанные партитуры (замерено). Убавь какие-то или сними одну с музыкальной половины.",
