"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "Любая модель с openrouter.ai/models, в виде провайдер/модель; поле предлагает весь список по мере ввода, каждую с её ценой за миллион токенов на вход и выход. Быстрые варианты заполняют его.",
