"Export all": "Экспортировать всё",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "Экспортировать всё: каждый документ Писателя с его версиями, сделанными из него семплами и корзиной — в один файл (резервная копия)",
"Import a backup": "Импортировать копию",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy. Nothing here is written over": "Импортировать резервную копию Писателя: то, чего здесь нет, придёт; то же самое не тронется; документ, отличающийся от своего тёзки здесь, ляжет рядом копией. Ничего здесь не перезаписывается",
"A Writer backup to import": "Резервная копия Писателя для импорта",
"The documents column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "Колонка документов: тяни, чтобы расширить; ← → с клавиатуры; Home или двойной клик — исходная ширина",
"Writer backup: {0} documents and {1} in the trash, into {2}": "Резервная копия Писателя: {0} документов и {1} в корзине — в {2}",
"not a Writer backup (a file this room exported)": "это не резервная копия Писателя (файл, который экспортировала эта комната)",
"Writer backup {0}: {1} new, {2} already here, {3} beside their namesakes as copies, {4} into the trash": "Резервная копия Писателя {0}: новых {1}, уже здесь {2}, копиями рядом с тёзками {3}, в корзину {4}",
