"{#0} takes carry a score you can remix.": { "one": "У {#0} семпла есть партитура, которую можно ремиксовать.", "few": "У {#0} семплов есть партитура, которую можно ремиксовать.", "many": "У {#0} семплов есть партитура, которую можно ремиксовать.", "other": "У {#0} семплов есть партитура, которую можно ремиксовать." },
